import type { RerunScope, RerunSelection } from './types.js';

// The server writes a run's outcomes asynchronously after finalization —
// sub-second warm, ~30s on a cold pipeline — so a re-run waits rather than
// concluding nothing failed. Bounded, so a run that never extracts fails with
// a message instead of hanging CI.
const NOT_READY_BUDGET_MS = 90_000;
const NOT_READY_POLL_MS = 2_000;
// Per request: the budget above only bounds retries, not a stalled socket.
const REQUEST_TIMEOUT_MS = 15_000;

export class RerunSelectionError extends Error {
  constructor(
    message: string,
    readonly code?: string
  ) {
    super(message);
    this.name = 'RerunSelectionError';
  }
}

export interface FetchSelectionOptions {
  serverUrl: string;
  token: string;
  runId: string;
  scope: RerunScope;
  testIds?: string[];
  excludeTestIds?: string[];
  fetchImpl?: typeof fetch;
  sleep?: (ms: number) => Promise<void>;
  now?: () => number;
}

const defaultSleep = (ms: number): Promise<void> => new Promise((resolve) => setTimeout(resolve, ms));

export function rerunSelectionPath(runId: string): string {
  return `/api/v1/reporter/runs/${encodeURIComponent(runId)}/rerun-selection`;
}

// Retries only SELECTION_NOT_READY; every other failure is terminal, because
// re-running the wrong set is worse than stopping.
export async function fetchRerunSelection(options: FetchSelectionOptions): Promise<RerunSelection> {
  const { fetchImpl = fetch, sleep = defaultSleep, now = Date.now } = options;
  const url = `${options.serverUrl.replace(/\/+$/, '')}${rerunSelectionPath(options.runId)}`;
  const body = JSON.stringify({
    ...(options.testIds?.length ? { testIds: options.testIds } : { scope: options.scope }),
    ...(options.excludeTestIds?.length ? { excludeTestIds: options.excludeTestIds } : {}),
  });
  const deadline = now() + NOT_READY_BUDGET_MS;

  for (;;) {
    const response = await fetchImpl(url, {
      method: 'POST',
      headers: { Authorization: `Bearer ${options.token}`, 'Content-Type': 'application/json' },
      body,
      signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
    }).catch((error: unknown) => {
      throw new RerunSelectionError(
        `Could not reach ${url}: ${error instanceof Error ? error.message : String(error)}`
      );
    });
    if (response.ok) {
      return await readSelection(response, url);
    }

    const code = await readErrorCode(response);
    if (code === 'SELECTION_NOT_READY' && now() < deadline) {
      await sleep(NOT_READY_POLL_MS);
      continue;
    }
    throw new RerunSelectionError(describeFailure(response.status, code, options.runId, url), code);
  }
}

// A proxy or login page can answer 200 with HTML; this client must never hand
// Playwright a list it did not look at.
async function readSelection(response: Response, url: string): Promise<RerunSelection> {
  let body: Partial<RerunSelection> | undefined;
  try {
    body = (await response.json()) as Partial<RerunSelection>;
  } catch {
    body = undefined;
  }
  if (!body || !Array.isArray(body.testList) || typeof body.resolution?.selected !== 'number') {
    throw new RerunSelectionError(`Unexpected response from ${url}: not a re-run selection.`);
  }
  return body as RerunSelection;
}

async function readErrorCode(response: Response): Promise<string | undefined> {
  try {
    const parsed = (await response.json()) as { error?: { code?: string } };
    return parsed?.error?.code;
  } catch {
    return undefined;
  }
}

function describeFailure(status: number, code: string | undefined, runId: string, url: string): string {
  // Every refusal this API makes carries an error code. A 5xx without one came
  // from whatever sits in front of it — a proxy, a Cloudflare tunnel (530), a
  // load balancer — so naming the URL points at the unreachable server instead
  // of reading as a verdict about the selection.
  if (status >= 500 && !code) {
    return `Could not reach the TestDino API at ${url} (HTTP ${status}). The server, or something in front of it, answered with an error instead of a re-run selection — check the server URL and that the service is up.`;
  }
  switch (code) {
    case 'RUN_NOT_FOUND':
      return `Run ${runId} is unknown, belongs to another project, or is not accessible with this token.`;
    case 'RUN_NOT_FINALIZED':
      return `Run ${runId} has not finished yet, so its failed set is incomplete.`;
    case 'SELECTION_NOT_READY':
      return `Run ${runId} finished but its results were never processed within ${NOT_READY_BUDGET_MS / 1000}s. Check the run in TestDino before retrying.`;
    case 'INVALID_PARAM':
      return `The re-run selection request for ${runId} was rejected as invalid.`;
    default:
      return `Could not resolve the re-run selection for ${runId} (HTTP ${status}${code ? ` ${code}` : ''}).`;
  }
}
