import { parseRunAttempt } from '../../metadata/ci.js';
import { supportsTestList } from './prepare.js';
import { defaultListRunner, listShard, listTestIds } from './verify.js';
import type { ListRunner } from './verify.js';
import type { RerunSelection } from './types.js';

// Same budget as an explicit --rerun: extract lands seconds after a run ends.
const NOT_READY_BUDGET_MS = 90_000;
const NOT_READY_POLL_MS = 2_000;
const REQUEST_TIMEOUT_MS = 15_000;
const PIPELINE_ID = /^[0-9]{1,20}$/;
const USER_TEST_LIST_FLAGS = ['--test-list', '--test-list-invert', '--list'];

export const CI_RERUN_SELECTION_PATH = '/api/v1/reporter/ci-reruns/selection';

export interface InRunRerunOptions {
  env: NodeJS.ProcessEnv;
  serverUrl: string;
  token?: string;
  playwrightArgs: string[];
  isSplit: boolean;
  readPlaywrightVersion: () => string | undefined;
  listRunner?: ListRunner;
  fetchImpl?: typeof fetch;
  sleep?: (ms: number) => Promise<void>;
  now?: () => number;
}

export type InRunRerunResult =
  | { kind: 'skip' }
  | { kind: 'full'; reason: string }
  // A split retry: runs its whole share, but still linked to the source run so
  // the dashboard labels it and run-level metrics leave it out.
  | { kind: 'link'; attempt: number; sourceRunId: string; reason: string }
  | {
      kind: 'narrow';
      attempt: number;
      selection: RerunSelection;
      // The job's real shard, so the retried jobs of one attempt still group
      // into a single run even though each executes --shard=1/1.
      shard?: { current: number; total: number };
    };

const defaultSleep = (ms: number): Promise<void> => new Promise((resolve) => setTimeout(resolve, ms));

/**
 * On a GitHub Actions retry, asks TestDino which of this invocation's tests
 * failed in the earlier attempt (microservices docs/RERUN_FAILED_TESTS.md §14).
 * Never throws: every failure is `full`, so the user's command runs unchanged
 * rather than a red job turning green on a partial run.
 */
export async function resolveInRunRerun(options: InRunRerunOptions): Promise<InRunRerunResult> {
  const { env } = options;
  const attempt = parseRunAttempt(env.GITHUB_RUN_ATTEMPT);
  const pipelineId = env.GITHUB_RUN_ID ?? '';
  if (env.GITHUB_ACTIONS !== 'true' || attempt === undefined || attempt < 2 || !PIPELINE_ID.test(pipelineId)) {
    return { kind: 'skip' };
  }
  if (!options.token) {
    return { kind: 'skip' };
  }
  const playwrightVersion = options.readPlaywrightVersion();
  if (!supportsTestList(playwrightVersion)) {
    return { kind: 'full', reason: `Playwright ${playwrightVersion ?? '(unknown)'} has no --test-list` };
  }
  const ownSelector = options.playwrightArgs.find((arg) =>
    USER_TEST_LIST_FLAGS.some((flag) => arg === flag || arg.startsWith(`${flag}=`))
  );
  if (ownSelector) {
    return { kind: 'full', reason: `the command already passes ${ownSelector}` };
  }

  try {
    const listJson = await (options.listRunner ?? defaultListRunner)(options.playwrightArgs);
    const listed = listTestIds(listJson);
    const answer = await fetchCISelection(options, { pipelineId, attempt, testIds: listed });
    if (answer.narrow !== true) {
      return { kind: 'full', reason: describeReason(answer.reason) };
    }
    if (!Array.isArray(answer.testList) || answer.testList.length === 0 || typeof answer.sourceRunId !== 'string') {
      return { kind: 'full', reason: 'the server answered without a selection' };
    }
    if (options.isSplit) {
      return typeof answer.sourceRunId === 'string'
        ? { kind: 'link', attempt, sourceRunId: answer.sourceRunId, reason: 'a split runs its whole share' }
        : { kind: 'full', reason: 'a split runs its whole share' };
    }
    const shard = listShard(listJson);
    return {
      kind: 'narrow',
      attempt,
      selection: answer as RerunSelection,
      ...(shard && shard.total > 1 && { shard }),
    };
  } catch (error) {
    return { kind: 'full', reason: error instanceof Error ? error.message : String(error) };
  }
}

interface CISelectionAnswer extends Partial<RerunSelection> {
  narrow?: boolean;
  reason?: string;
}

async function fetchCISelection(
  options: InRunRerunOptions,
  body: { pipelineId: string; attempt: number; testIds: string[] }
): Promise<CISelectionAnswer> {
  const { fetchImpl = fetch, sleep = defaultSleep, now = Date.now } = options;
  const url = `${options.serverUrl.replace(/\/+$/, '')}${CI_RERUN_SELECTION_PATH}`;
  const payload = JSON.stringify(body);
  const deadline = now() + NOT_READY_BUDGET_MS;

  for (;;) {
    const response = await fetchImpl(url, {
      method: 'POST',
      headers: { Authorization: `Bearer ${options.token}`, 'Content-Type': 'application/json' },
      body: payload,
      signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
    });
    let parsed: (CISelectionAnswer & { error?: { code?: string } }) | undefined;
    try {
      parsed = (await response.json()) as CISelectionAnswer & { error?: { code?: string } };
    } catch {
      parsed = undefined;
    }
    if (response.ok && parsed) {
      return parsed;
    }
    const code = parsed?.error?.code;
    if (code === 'SELECTION_NOT_READY' && now() < deadline) {
      await sleep(NOT_READY_POLL_MS);
      continue;
    }
    throw new Error(`TestDino answered HTTP ${response.status}${code ? ` ${code}` : ''}`);
  }
}

function describeReason(reason: string | undefined): string {
  switch (reason) {
    case 'NO_INTENT':
      return 'this retry was not started from TestDino';
    case 'NOTHING_FAILED':
      return 'none of these tests failed in the earlier attempt';
    case 'NOT_COVERED':
      return 'some of these tests did not run in the earlier attempt';
    case 'MULTIPLE_SOURCES':
      return 'the earlier failures span more than one TestDino run';
    case 'TOO_MANY_TESTS':
      return 'the suite is too large to narrow';
    default:
      return reason ? `TestDino answered ${reason}` : 'TestDino gave no reason';
  }
}
