import { readFileSync, unlinkSync, writeFileSync } from 'fs';
import { tmpdir } from 'os';
import { dirname, join, resolve } from 'path';
import { randomUUID } from 'crypto';

// --test-list landed in 1.56.0. Below it the only selector that takes a file
// needs the config evaluated, and a wrong guess re-runs the WHOLE suite while
// reporting success.
export const MIN_TEST_LIST_VERSION = [1, 56, 0] as const;

const RERUN_FLAGS = ['--rerun', '--from-run', '--test-ids', '--exclude-ids', '--rerun-tags'];
const CONFLICTING_FLAGS = ['--test-list', '--test-list-invert', '--last-failed', '--grep', '-g', '--grep-invert'];
const SHARD_FLAG = '--shard';

function hasFlag(args: string[], flags: string[]): string | undefined {
  return args.find((arg) => flags.some((flag) => arg === flag || arg.startsWith(`${flag}=`)));
}

// Commander does not parse options after `--`; a rerun flag there would reach
// Playwright as an unknown option, or be dropped, and the whole suite would run.
export function misplacedRerunFlag(playwrightArgs: string[]): string | undefined {
  return hasFlag(playwrightArgs, RERUN_FLAGS);
}

// A user selector would either be overridden by the selection or silently
// widen it; neither is safe to guess at.
export function conflictingSelector(playwrightArgs: string[]): string | undefined {
  return hasFlag(playwrightArgs, CONFLICTING_FLAGS);
}

// Sharding splits by count: a few re-run tests land on one shard and every
// other shard finds nothing and exits 1 — a red pipeline that ran nothing.
export function hasShardFlag(playwrightArgs: string[]): boolean {
  return hasFlag(playwrightArgs, [SHARD_FLAG]) !== undefined;
}

export function parseVersion(raw: string | undefined): [number, number, number] | undefined {
  const match = raw ? /^(\d+)\.(\d+)\.(\d+)/.exec(raw.trim()) : null;
  return match ? [Number(match[1]), Number(match[2]), Number(match[3])] : undefined;
}

// An unreadable version counts as unsupported: guessing risks the whole-suite
// failure mode above.
export function supportsTestList(raw: string | undefined): boolean {
  const version = parseVersion(raw);
  if (!version) return false;
  for (let i = 0; i < MIN_TEST_LIST_VERSION.length; i++) {
    if (version[i] > MIN_TEST_LIST_VERSION[i]) return true;
    if (version[i] < MIN_TEST_LIST_VERSION[i]) return false;
  }
  return true;
}

// Resolved from the project the CLI was invoked in, not from this package's
// own tree, by walking up: the CLI ships as an ESM bundle where a bare
// require.resolve throws the same way for "not installed".
export function readInstalledPlaywrightVersion(cwd: string = process.cwd()): string | undefined {
  let dir = resolve(cwd);
  for (;;) {
    try {
      const parsed = JSON.parse(
        readFileSync(join(dir, 'node_modules', '@playwright', 'test', 'package.json'), 'utf-8')
      ) as {
        version?: string;
      };
      if (typeof parsed.version === 'string' && parsed.version !== '') return parsed.version;
    } catch {
      // Not at this level — keep walking.
    }
    const parent = dirname(dir);
    if (parent === dir) return undefined;
    dir = parent;
  }
}

// Lives in the OS temp dir: a file inside the project would be a stale
// selection a later plain `playwright test --test-list` could pick up.
export class SelectionFile {
  private path?: string;

  write(lines: string[]): string {
    this.path = join(tmpdir(), `testdino-rerun-${randomUUID()}.txt`);
    writeFileSync(this.path, `${lines.join('\n')}\n`, 'utf-8');
    return this.path;
  }

  cleanup(): void {
    if (!this.path) return;
    try {
      unlinkSync(this.path);
    } catch {
      // Already reclaimed by the OS.
    }
    this.path = undefined;
  }
}
